package com.nerijus.cadence.network

import java.util.Locale
import kotlin.math.max

object ArtistName {
    private const val TOPIC_SUFFIX = " - Topic"

    /** Auto-generated artist channels are named "Artist - Topic"; show just the artist. */
    fun clean(channelTitle: String): String = channelTitle.removeSuffix(TOPIC_SUFFIX)

    /** YouTube's auto-generated artist channels, which carry the album versions of songs. */
    fun isTopicChannel(channelTitle: String): Boolean = channelTitle.endsWith(TOPIC_SUFFIX)
}

/** Case- and accent-insensitive containment, for names that differ between services. */
fun String.looselyContains(other: String): Boolean =
    other.isNotEmpty() && foldedForMatching().contains(other.foldedForMatching())

/** Either name contains the other, for "Artist" vs "Artist & Friend". */
fun String.looselyMatches(other: String): Boolean = looselyContains(other) || other.looselyContains(this)

private val combiningMarks = Regex("\\p{Mn}+")

private fun String.foldedForMatching(): String =
    combiningMarks.replace(java.text.Normalizer.normalize(this, java.text.Normalizer.Form.NFD), "").lowercase()

/**
 * The credits YouTube writes into its auto-generated music videos: "Provided to YouTube by Label",
 * then "Song · Artist · Other Artist", then the album. Their "Topic" channels are sometimes named
 * after a distributor, such as "Release - Topic", so this is the only reliable artist.
 */
class AutoGeneratedCredits private constructor(val artists: List<String>, val album: String?) {

    /** "A", "A & B" or "A, B & C", as Apple Music writes them. */
    val artist: String
        get() = if (artists.size > 1) {
            artists.dropLast(1).joinToString(", ") + " & " + artists.last()
        } else {
            artists.joinToString("")
        }

    companion object {
        private const val HEADER = "Provided to YouTube by"
        private const val SEPARATOR = " · "
        private val rightsPrefixes = listOf("℗", "©", "Released on:")

        fun parse(description: String): AutoGeneratedCredits? {
            val lines = description.lines().map(String::trim).filter(String::isNotEmpty)
            if (lines.size < 2 || !lines[0].startsWith(HEADER)) return null
            val names = lines[1].split(SEPARATOR).drop(1).map(String::trim).filter(String::isNotEmpty)
            if (names.isEmpty()) return null
            val album = lines.getOrNull(2)?.takeUnless { line -> rightsPrefixes.any(line::startsWith) }
            return AutoGeneratedCredits(names, album)
        }
    }
}

/**
 * What a video's title says about its recording. Music videos often add intros, skits and
 * outros, so synced lyrics timed against the album audio drift on them.
 */
object VideoTitle {
    private val musicVideo = Regex("""(?i)\b(official\s+(4k\s+|hd\s+|music\s+)?video|music\s+video|m/?v)\b""")
    private val audio = Regex("""(?i)\baudio\b""")
    private val lyricVideo = Regex("""(?i)\b(lyrics?|visuali[sz]er)\b""")
    private val video = Regex("""(?i)\b(video|m/?v)\b""")

    /** "Song (Official Music Video)" or "Song [MV]", but not "Song (Official Lyric Video)". */
    fun isMusicVideo(title: String): Boolean =
        musicVideo.containsMatchIn(title) && !isAudio(title) && !lyricVideo.containsMatchIn(title)

    /** "Song (Official Audio)". */
    fun isAudio(title: String): Boolean = audio.containsMatchIn(title)

    /** A search such as "song music video", whose results should keep YouTube's order. */
    fun asksForVideo(query: String): Boolean = video.containsMatchIn(query)
}

object Iso8601Duration {
    private const val SECONDS_PER_MINUTE = 60.0
    private const val SECONDS_PER_HOUR = 3_600.0
    private const val SECONDS_PER_DAY = 86_400.0
    private const val SECONDS_PER_WEEK = 604_800.0

    /** Parses YouTube durations such as "PT4M13S". Returns null for live streams ("P0D"). */
    fun seconds(value: String): Double? {
        if (!value.startsWith("P")) return null
        var total = 0.0
        val digits = StringBuilder()
        var isTimeSection = false
        for (character in value.drop(1)) {
            if (character == 'T') {
                isTimeSection = true
                continue
            }
            if (character.isDigit() || character == '.') {
                digits.append(character)
                continue
            }
            val amount = digits.toString().toDoubleOrNull() ?: return null
            digits.clear()
            total += amount * when {
                character == 'W' && !isTimeSection -> SECONDS_PER_WEEK
                character == 'D' && !isTimeSection -> SECONDS_PER_DAY
                character == 'H' && isTimeSection -> SECONDS_PER_HOUR
                character == 'M' && isTimeSection -> SECONDS_PER_MINUTE
                character == 'S' && isTimeSection -> 1.0
                else -> return null
            }
        }
        return total.takeIf { it > 0 }
    }
}

object TimeFormatting {
    private const val SECONDS_PER_MINUTE = 60
    private const val SECONDS_PER_HOUR = 3_600

    /** "4:13", or "1:02:03" past an hour. */
    fun string(seconds: Double): String {
        val whole = max(0, seconds.toInt())
        val hours = whole / SECONDS_PER_HOUR
        val minutes = whole % SECONDS_PER_HOUR / SECONDS_PER_MINUTE
        val remainder = whole % SECONDS_PER_MINUTE
        return if (hours > 0) {
            String.format(Locale.ROOT, "%d:%02d:%02d", hours, minutes, remainder)
        } else {
            String.format(Locale.ROOT, "%d:%02d", minutes, remainder)
        }
    }
}

object HtmlEntity {
    private const val MAX_ENTITY_LENGTH = 10
    private const val HEX_RADIX = 16
    private val named = mapOf("amp" to "&", "quot" to "\"", "apos" to "'", "lt" to "<", "gt" to ">", "nbsp" to " ")

    private fun decode(entity: String): String? {
        named[entity]?.let { return it }
        if (!entity.startsWith("#")) return null
        val number = entity.drop(1)
        val codePoint = if (number.startsWith("x", ignoreCase = true)) {
            number.drop(1).toIntOrNull(HEX_RADIX)
        } else {
            number.toIntOrNull()
        }
        return codePoint?.takeIf(Character::isValidCodePoint)?.let { String(Character.toChars(it)) }
    }

    /** The search endpoint returns HTML-escaped titles (e.g. `Don&#39;t Stop`). */
    fun decodeAll(text: String): String {
        if ('&' !in text) return text
        val result = StringBuilder()
        var index = 0
        while (index < text.length) {
            val semicolon = text.indexOf(';', index)
            val decoded = if (text[index] == '&' && semicolon > index && semicolon - index <= MAX_ENTITY_LENGTH) {
                decode(text.substring(index + 1, semicolon))
            } else {
                null
            }
            if (decoded != null) {
                result.append(decoded)
                index = semicolon + 1
            } else {
                result.append(text[index])
                index += 1
            }
        }
        return result.toString()
    }
}
